// `defaultValue` is what the storefront itself uses when the key is unset, so an untouched slider or
// toggle shows the real setting instead of its minimum / "off".
export type StyleField =
  | { key: string; label: string; defaultValue?: any; kind: "text" | "textarea" | "color" | "toggle" | "image" | "html" | "link" }
  | { key: string; label: string; defaultValue?: any; kind: "range" | "number"; min: number; max: number; step?: number; suffix?: string }
  | { key: string; label: string; defaultValue?: any; kind: "select"; options: { value: string; label: string }[] };

export type StyleGroup = { id: string; title: string; hint?: string; fields: StyleField[] };

/** "No scheme": the part keeps the theme's own colours. */
export const NO_SCHEME = { value: "", label: "Theme colours (no scheme)" };
/** A colour-scheme select (Theme settings › Colour schemes) with the design's current schemes as choices. */
export function schemeFieldOptions(field: StyleField, schemes: { id: string; name: string }[]): StyleField {
  if (!field.key.startsWith("elementSchemes.") || field.kind !== "select") return field;
  return { ...field, options: [NO_SCHEME, ...schemes.map((s) => ({ value: s.id, label: s.name || s.id }))] };
}

const opts = (...v: string[]) => v.map((x) => ({ value: x, label: x[0].toUpperCase() + x.slice(1) }));
const weights = ["300", "400", "500", "600", "700", "800", "900"].map((w) => ({ value: w, label: w }));

// When a preview region is clicked, Studio pins an "Editing: <label>" card with just that region's
// controls. A label listed here gathers its fields from ANY group by key; other labels show their
// whole target group.
export const STYLE_TARGET_FIELDS: Record<string, RegExp> = {
  ...Object.fromEntries(REGION_GROUPS.flatMap(g => g.regions.map(r => [r.label, new RegExp(`^regions\\.${r.id}(Tablet|Mobile)?(${REGION_SUFFIXES.join("|")})$`)]))),
  "Announcement bar": /^(showAnnouncement|announcement)/,
  "Card title & price": /^(productTitleColor|productPriceColor|cardTitle|cardPrice|cardCreator|cardFormats|cardRating|catalogPriceStyle|catalogTitleTransform|catalogCardRuleWidth|elementSchemes\.cards$)/,
  "Buy card": /^(elementSchemes\.buyCard$|pdpCard|pdpRuledRows|pdpShowTag|pdpTag|pdpTitle|pdpPrice|pdpShowStock|pdpStock|productCta|addToBagLabel|showQtyStepper|showSocialShare|showPdpWishlist|showBackInStock|showComingSoonSignup)/,
  "Back-in-stock signup": /^(showBackInStock$|pdpAlert)/,
  "Edition choices": /^(pdpEditionPicker$|pdpChip)/,
  "Coming soon signup": /^(showComingSoonSignup$|pdpAlert)/,
  "Product title & price": /^(pdpTitle|pdpPrice|productTitleSize|productSubtitleWeight)/,
  "Product photos": /^(productPhotoOutline|pdpThumb|pdpPhoto|pdpShowCaption|pdpPhotoDots|productImage|productBorderRadius|showZoom|showPdpMagnifier|pdpMagnifier|showPhotoLightbox|showProductVideos|pdpViewer)/,
  "Enlarged photo viewer": /^(showPhotoLightbox$|pdpViewer)/,
  "Product details tabs": /^(pdpDetailsPlacement|pdpSpecsStyle|pdpTab|pdpPanel|productDetailsLayout|showSpecs)/,
  "Breadcrumb": /^(pdpShowBreadcrumb|pdpShowBackLink|pdpShowBackArrow|pdpMeta)/,
  "Back link": /^(pdpShowBackLink$|pdpShowBackArrow$|pdpMeta)/,
  "Footer brand": /^(footerLogo|logoUrl|logoColor|logoTint|wordmark)/,
  "Bag heading": /^(elementSchemes\.cartDrawer$|cartDrawer(Title|Meta|ShowCount|Padding|Edge))/,
  "Free-shipping bar": /^(showFreeShipBar|cartDrawerProgress)/,
  "Bag line items": /^(cartDrawer(ShowItemNumbers|ShowPreorder|ShowLineOptions|Thumb|GrayscaleThumbs|ItemTitleSize|ShowUnitPrice|ShowLineTotal|QtyStyle|RemoveStyle|Border|Muted))/,
  "Bag suggestion": /^(cartDrawer(ShowUpsell|UpsellShadow|Surface|GrayscaleThumbs))/,
  "Empty bag": /^cartDrawer(ShowEmpty|Empty)/,
  "Bag discount code": /^cartDrawer(ShowDiscountCode|Surface|Border|Muted)$/,
  "Bag order note": /^cartDrawer(ShowOrderNote|Surface|Border|Muted)$/,
  "Added-to-bag notice": /^(cartAdd(Action|NoticeSeconds)$|cartDrawer(Side|Bg|Text|Muted|Surface|Edge|Checkout|Meta|Title|Thumb))/,
  "Bag total & checkout": /^(cartDrawer(ShowSummary|TotalSize|Checkout|ShowCheckoutArrow|ShowDeliveryNote|ShowTermsCheckbox|Show(Secure|Tracked|Returns)Badge)|showCartTrustBadges)/,
};

